document.addEventListener("DOMContentLoaded", function () {
  const toggleButton = document.getElementById("sidebar-toggle");
  const root = document.documentElement;

  // Função para aplicar o estado inicial do menu
  const applyInitialSidebarState = () => {
    const isCollapsed = localStorage.getItem("sidebarCollapsed") === "true";
    if (isCollapsed) {
      root.classList.add("sidebar-collapsed");
    }
  };

  toggleButton.addEventListener("click", () => {
    root.classList.toggle("sidebar-collapsed");
    localStorage.setItem("sidebarCollapsed", root.classList.contains("sidebar-collapsed"));
  });
  // Adiciona o evento apenas se o botão existir na página
  if (toggleButton) {
    toggleButton.addEventListener("click", () => {
      root.classList.toggle("sidebar-collapsed");
      localStorage.setItem("sidebarCollapsed", root.classList.contains("sidebar-collapsed"));
    });

  applyInitialSidebarState();
    // Aplica o estado inicial apenas se o botão estiver presente
    applyInitialSidebarState();
  }
});
